// WF2 - Parse callback + authorization (CON ASSEGNA + DRIVER ASSIGN)

function toStr(v) { return (v ?? '').toString().trim(); }
function toInt(v) {
  const n = Number(toStr(v));
  return Number.isFinite(n) ? n : null;
}

function parseCallbackData(dataRaw) {
  const data = toStr(dataRaw);
  if (!data) throw new Error('WF2: callback_data vuota');

  const parts = data.split('|').map(p => (p ?? '').toString().trim());
  let decision = (parts[0] || '').toUpperCase().replace(/[^A-Z]/g, '');

  if (decision === 'SI' || decision === 'OK') decision = 'YES';
  if (decision === 'KO') decision = 'NO';

  // ===== DRIVER ASSIGN: D|nomeAutista (ID estratto dal testo messaggio) =====
  if (decision === 'D') {
    if (parts.length < 2) {
      throw new Error(`WF2: formato D richiede D|nomeAutista, ricevuto: "${data}"`);
    }
    // L'ID non è nel callback (limite 64 byte), lo estraiamo dal testo del messaggio
    // Il Build Driver Keyboard aggiunge "Ref: <ID>" alla fine del messaggio
    const msgText = (cq?.message?.text || '');
    const refMatch = msgText.match(/Ref:\s*(.+)/);
    const extractedId = refMatch ? refMatch[1].trim() : '';
    if (!extractedId) {
      throw new Error(`WF2: ID non trovato nel testo messaggio (Ref mancante)`);
    }
    return {
      decision: 'YES',
      driverName: parts[1],
      id: extractedId,
      isDriverAssign: true
    };
  }

  // ===== ASSEGNA: ASSEGNA|id =====
  if (decision === 'ASSEGNA') {
    return {
      decision: 'ASSEGNA',
      id: parts.length >= 2 ? parts.slice(1).join('|') : '',
      isDriverAssign: false,
      driverName: ''
    };
  }

  if (!['YES', 'NO', 'ESEGUITO'].includes(decision)) {
    throw new Error(`WF2: decision non valida: "${parts[0]}" (normalized: "${decision}") | raw: "${data}"`);
  }

  // LEGACY: YES|spreadsheetId|sheetName|rowIndex|id
  if (parts.length >= 5) {
    return { decision, spreadsheetId: parts[1], sheetName: parts[2], rowIndex: toInt(parts[3]), id: parts.slice(4).join('|'), isDriverAssign: false, driverName: '' };
  }
  // ATTUALE: YES|rowIndex|id
  if (parts.length === 3) {
    return { decision, rowIndex: toInt(parts[1]), id: parts[2], isDriverAssign: false, driverName: '' };
  }
  // MINIMO: YES|id
  if (parts.length === 2) {
    return { decision, id: parts[1], isDriverAssign: false, driverName: '' };
  }

  throw new Error(`WF2: callback_data non valida: "${data}"`);
}

const cq = $json.callback_query ?? $json;
const dataRaw   = cq?.data ?? null;
const actorId   = cq?.from?.id ?? null;
const actorUser = cq?.from?.username ?? cq?.from?.first_name ?? '';
const messageId = cq?.message?.message_id ?? null;
const chatId    = cq?.message?.chat?.id ?? null;
// Salva il testo originale del messaggio per poterlo riusare
const originalText = cq?.message?.text ?? '';

const parsed = parseCallbackData(dataRaw);

const ALLOWED = [522233722];
const unauthorized = (ALLOWED.length > 0) && (actorId != null) && (!ALLOWED.includes(Number(actorId)));

return [{
  json: {
    ...parsed,
    unauthorized,
    telegramContext: { chatId, messageId },
    originalText,
    actor: { actorId, actorUser },
    rawCallback: toStr(dataRaw)
  }
}];

// ===============================
// INPUT — dati transfer da "Cerca id sheet"
// ===============================
const data = $('Cerca id sheet').item.json;

// ===============================
// UTILS
// ===============================
const toStr = (v) => {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v.trim();
  return String(v).trim();
};

const toNum = (v) => {
  const s0 = toStr(v);
  if (!s0) return null;
  let s = s0.replace(/\s+/g, "");
  s = s.replace(/[€$£]/g, "");
  if (s.includes(",")) {
    s = s.replace(/\./g, "").replace(/,/g, ".");
  }
  s = s.replace(/[^0-9.+-]/g, "");
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const formatIT = (n) => {
  if (n === null || n === undefined || !Number.isFinite(n)) return "";
  return n.toFixed(2).replace(".", ",");
};

// ===============================
// LINGUA DAL NODO AI (Detect Language)
// ===============================
let lang = "en";
try {
  const aiOutput = $('Detect Language').item.json;
  const aiText = (
    aiOutput?.output?.[0]?.content?.[0]?.text ??
    aiOutput?.message?.content ??
    aiOutput?.content ??
    aiOutput?.text ??
    ""
  ).toString().toLowerCase().trim();
  lang = aiText.startsWith("it") ? "it" : "en";
} catch (e) {
  lang = "en";
}

// ===============================
// NOME STRUTTURA DINAMICO (dal Fornitore)
// ===============================
const nomeStruttura = toStr(data.Fornitore) || "Transfer Experience";

// ===============================
// ESTRAI DATI
// ===============================
const dataServizio = toStr(data.Data);
const ora = toStr(data.Time);
const trs_da = toStr(data['TRS> DA']);
const trs_per = toStr(data['TRS <PER']);
const nome = toStr(data.Nome);
const pax = toStr(data.PAX);
const volo = toStr(data.Volo);
const note = toStr(data.Note);
const cellulare = toStr(data['cell.']);
const modalita = toStr(data['Modalità']);
const tariffa = toNum(data['Tariffa '] || data.Tariffa);
const email = toStr(data['n. pratica']);
const hExtra = toStr(data['h extra/ritardi']);

// ===============================
// AUTO-DETECT VEICOLO IN BASE A PAX
// ===============================
const paxNum = parseInt(pax) || 0;
let veicolo = toStr(data.Veicolo);

if (!veicolo) {
  if (paxNum >= 1 && paxNum <= 2) {
    veicolo = "Auto";
  } else if (paxNum >= 3 && paxNum <= 7) {
    veicolo = "Minivan";
  } else if (paxNum >= 8) {
    veicolo = "Minibus";
  }
}

// ===============================
// TESTI MULTILINGUA (struttura dinamica)
// ===============================
const texts = {
  it: {
    subject: (nome, data, ora) => `🚗 Conferma Transfer - ${nome || 'Ospite'} - ${data} ore ${ora}`,
    title: "Conferma Prenotazione Transfer",
    subtitle: nomeStruttura,
    greeting: (nome) => nome ? `Gentile ${nome},` : "Gentile Ospite,",
    intro: `La ringraziamo per aver prenotato il servizio transfer con ${nomeStruttura}. Di seguito i dettagli della sua prenotazione:`,
    detailsTitle: "Dettagli del Transfer",
    date: "Data",
    time: "Ora",
    from: "Partenza",
    to: "Destinazione",
    pax: "Passeggeri",
    flight: "Volo",
    vehicle: "Veicolo",
    phone: "Telefono",
    notes: "Note",
    price: "Tariffa",
    hExtra: "Ore extra / Ritardi",
    policyTitle: "⚠️ Politica di Cancellazione",
    policyFree: "✅ Cancellazione GRATUITA fino a 24 ore prima del servizio",
    policyPaid: "❌ Cancellazione entro le 24 ore: addebito del 100% della tariffa",
    policyNote: "Per modifiche o cancellazioni, contattare tempestivamente la struttura.",
    calendarBtn: "📅 Aggiungi a Google Calendar",
    footer: `Transfer Experience per ${nomeStruttura}`,
    questions: "Per qualsiasi domanda, non esiti a contattarci.",
    nd: "N/D"
  },
  en: {
    subject: (nome, data, ora) => `🚗 Transfer Confirmation - ${nome || 'Guest'} - ${data} at ${ora}`,
    title: "Transfer Booking Confirmation",
    subtitle: nomeStruttura,
    greeting: (nome) => nome ? `Dear ${nome},` : "Dear Guest,",
    intro: `Thank you for booking your transfer service with ${nomeStruttura}. Please find below your booking details:`,
    detailsTitle: "Transfer Details",
    date: "Date",
    time: "Time",
    from: "Pick-up",
    to: "Drop-off",
    pax: "Passengers",
    flight: "Flight",
    vehicle: "Vehicle",
    phone: "Phone",
    notes: "Notes",
    price: "Fare",
    hExtra: "Extra hours / Delays",
    policyTitle: "⚠️ Cancellation Policy",
    policyFree: "✅ FREE cancellation up to 24 hours before the service",
    policyPaid: "❌ Cancellation within 24 hours: 100% of the fare will be charged",
    policyNote: "For changes or cancellations, please contact us promptly.",
    calendarBtn: "📅 Add to Google Calendar",
    footer: `Transfer Experience for ${nomeStruttura}`,
    questions: "If you have any questions, please don't hesitate to contact us.",
    nd: "N/A"
  }
};

const t = texts[lang];

// ===============================
// CREA LINK GOOGLE CALENDAR
// ===============================
let calendarLink = '';

if (dataServizio && ora) {
  const [giorno, mese, anno] = dataServizio.split('/');
  const [oreStr, minutiStr] = ora.split(':');

  const startDateTime = `${anno}${mese}${giorno}T${oreStr}${minutiStr}00`;

  const oreNum = parseInt(oreStr);
  const oreFine = String(oreNum + 2).padStart(2, '0');
  const endDateTime = `${anno}${mese}${giorno}T${oreFine}${minutiStr}00`;

  const title = encodeURIComponent(`Transfer: ${nome || 'Guest'} - ${nomeStruttura}`);
  const dates = `${startDateTime}/${endDateTime}`;
  const location = encodeURIComponent(`${trs_da} → ${trs_per}`);

  const detailsText = [
    lang === 'it' ? `Cliente: ${nome || 'N/D'}` : `Guest: ${nome || 'N/A'}`,
    `Pax: ${pax || t.nd}`,
    lang === 'it' ? `Volo: ${volo || t.nd}` : `Flight: ${volo || t.nd}`,
    lang === 'it' ? `Veicolo: ${veicolo || t.nd}` : `Vehicle: ${veicolo || t.nd}`,
    lang === 'it' ? `Cellulare: ${cellulare || t.nd}` : `Phone: ${cellulare || t.nd}`,
    note ? (lang === 'it' ? `Note: ${note}` : `Notes: ${note}`) : ''
  ].filter(Boolean).join('\n');

  const details = encodeURIComponent(detailsText);

  calendarLink = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=${dates}&details=${details}&location=${location}`;
}

// ===============================
// COSTRUISCI EMAIL HTML
// ===============================
const emailSubject = t.subject(nome, dataServizio, ora);

const tariffaRow = tariffa !== null
  ? `<tr style="background-color: #f8f9fa;">
      <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">💰 ${t.price}</td>
      <td style="padding: 12px; border: 1px solid #dee2e6;">€ ${formatIT(tariffa)}</td>
    </tr>`
  : '';

const hExtraRow = hExtra
  ? `<tr>
      <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">⏱️ ${t.hExtra}</td>
      <td style="padding: 12px; border: 1px solid #dee2e6;">${hExtra}</td>
    </tr>`
  : '';

const noteRow = note
  ? `<tr style="background-color: #fff3cd;">
      <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">📝 ${t.notes}</td>
      <td style="padding: 12px; border: 1px solid #dee2e6;">${note}</td>
    </tr>`
  : '';

const emailBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="margin: 0; padding: 0; background-color: #f4f4f4;">
<div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #ffffff;">

  <!-- Header -->
  <div style="background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%); color: white; padding: 30px; text-align: center;">
    <h1 style="margin: 0; font-size: 24px; font-weight: 300;">${t.title}</h1>
    <p style="margin: 10px 0 0 0; font-size: 16px; opacity: 0.9;">${t.subtitle}</p>
  </div>

  <!-- Body -->
  <div style="padding: 30px;">

    <p style="color: #2c3e50; font-size: 16px; margin-bottom: 20px;">${t.greeting(nome)}</p>
    <p style="color: #555; font-size: 14px; line-height: 1.6;">${t.intro}</p>

    <h3 style="color: #2c3e50; border-bottom: 2px solid #3498db; padding-bottom: 10px; margin-top: 30px;">
      🚗 ${t.detailsTitle}
    </h3>

    <table style="width: 100%; border-collapse: collapse; margin: 20px 0;">
      <tr style="background-color: #f8f9fa;">
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold; width: 140px;">📅 ${t.date}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${dataServizio}</td>
      </tr>
      <tr>
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">🕐 ${t.time}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${ora}</td>
      </tr>
      <tr style="background-color: #f8f9fa;">
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">📍 ${t.from}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${trs_da || t.nd}</td>
      </tr>
      <tr>
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">📍 ${t.to}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${trs_per || t.nd}</td>
      </tr>
      <tr style="background-color: #f8f9fa;">
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">👥 ${t.pax}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${pax || t.nd}</td>
      </tr>
      ${volo ? `<tr>
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">✈️ ${t.flight}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${volo}</td>
      </tr>` : ''}
      ${veicolo ? `<tr style="background-color: #f8f9fa;">
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">🚐 ${t.vehicle}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${veicolo}</td>
      </tr>` : ''}
      ${cellulare ? `<tr>
        <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">📞 ${t.phone}</td>
        <td style="padding: 12px; border: 1px solid #dee2e6;">${cellulare}</td>
      </tr>` : ''}
      ${hExtraRow}
      ${tariffaRow}
      ${noteRow}
    </table>

    <!-- Policy Cancellazione -->
    <div style="background-color: #fef9e7; border: 2px solid #f1c40f; border-radius: 8px; padding: 20px; margin: 25px 0;">
      <h4 style="margin: 0 0 15px 0; color: #856404;">${t.policyTitle}</h4>
      <p style="margin: 8px 0; color: #155724; font-size: 14px;">${t.policyFree}</p>
      <p style="margin: 8px 0; color: #721c24; font-size: 14px;">${t.policyPaid}</p>
      <p style="margin: 15px 0 0 0; color: #856404; font-size: 13px; font-style: italic;">${t.policyNote}</p>
    </div>

    <!-- Bottoni Policy -->
    <div style="text-align: center; margin: 25px 0;">
      <a href="https://drive.google.com/file/d/18RfnfGLZPUKO_mhvKsh9sJA9gia3TB80/view" target="_blank" style="display: inline-block; background-color: #6c757d; color: #ffffff; padding: 10px 22px; margin: 0 6px; text-decoration: none; border-radius: 5px; font-weight: bold; font-size: 14px;">📄 Policy (IT)</a>
      <a href="https://drive.google.com/file/d/1JoeSpnB_pGdkYHEIxq4D7PCsy3N9EwiU/view" target="_blank" style="display: inline-block; background-color: #6c757d; color: #ffffff; padding: 10px 22px; margin: 0 6px; text-decoration: none; border-radius: 5px; font-weight: bold; font-size: 14px;">📄 Policy (EN)</a>
    </div>

    <!-- Bottone Calendar -->
    ${calendarLink ? `
    <div style="text-align: center; margin: 30px 0;">
      <a href="${calendarLink}" target="_blank" style="display: inline-block; background-color: #4285f4; color: white; padding: 15px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; font-size: 16px;">
        ${t.calendarBtn}
      </a>
    </div>
    ` : ''}

    <p style="color: #555; font-size: 14px; text-align: center; margin-top: 20px;">${t.questions}</p>

  </div>

  <!-- Footer -->
  <div style="background-color: #2c3e50; color: white; padding: 20px; text-align: center;">
    <p style="margin: 0; font-size: 12px; opacity: 0.8;">${t.footer}</p>
  </div>

</div>
</body>
</html>
`;

// ===============================
// OUTPUT
// ===============================
return [{
  json: {
    email: email,
    emailSubject: emailSubject,
    emailBody: emailBody,
    calendarLink: calendarLink,
    language: lang,
    nome: nome,
    dataServizio: dataServizio,
    ora: ora,
    Veicolo: veicolo,
    ...data
  }
}];

function s(v){ return (v ?? '').toString().trim(); }
function digits(v){ return s(v).replace(/[^\d]/g,''); }
function todayIT(){
  const d = new Date();
  const dd = String(d.getDate()).padStart(2,'0');
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const yy = d.getFullYear();
  return `${dd}/${mm}/${yy}`;
}

function formatNum(v) {
  if (v === '' || v === null || v === undefined) return '';
  const n = parseFloat(String(v).replace(',', '.'));
  if (!Number.isFinite(n)) return String(v).trim();
  return n.toFixed(2).replace('.', ',').replace(/,00$/, '');
}

// Sorgente: dati struttura dal nodo "Cerca id sheet"
const src = $('Cerca id sheet').item.json;

// Sorgente gestionale: dati esistenti da Prenotazioni NCC 3.0 (può essere vuoto se nuovo)
let gestionaleData = null;
try {
  const gItems = $('Get gestionale').all();
  if (gItems.length > 0) {
    gestionaleData = gItems[0].json;
  }
} catch (e) {}

const existsInGestionale = gestionaleData !== null;
const autistaGestionale = existsInGestionale ? s(gestionaleData.Autista) : '';
const veicoloGestionale = existsInGestionale ? s(gestionaleData.Veicolo) : '';

// =====================
// MODALITÀ RECOVERY
// =====================
const modalitaPatterns = [
  'incassare','contanti','carta','fattura','sconto in fattura',
  'dalla struttura','link','omaggio'
];
let modalitaVal = s(src['Modalità']);
let noteVal = s(src.Note);

if (modalitaVal === '' && noteVal !== '') {
  const noteLower = noteVal.toLowerCase();
  for (const pat of modalitaPatterns) {
    if (noteLower === pat) {
      modalitaVal = noteVal;
      noteVal = '';
      break;
    }
  }
}

// =====================
// DRIVER INJECTION (da bottone Telegram)
// =====================
let autista = s(src.Autista);
let driverAssigned = false;

try {
  const callbackData = $('Code - Parse Callback').item.json;
  if (callbackData.isDriverAssign && callbackData.driverName) {
    autista = callbackData.driverName;
    driverAssigned = true;
  }
} catch (e) {}

// PATCH 2026-07-23: IL GESTIONALE È PADRONE DI AUTISTA/VEICOLO.
// La colonna Autista nel foglio struttura è una COPIA che può essere stantia:
// se Agostino riassegna nel gestionale e poi approva una modifica della struttura,
// la copia vecchia sovrascriveva la riassegnazione (caso Gianvito→Katia 23/07).
// Regola: senza assegnazione esplicita da bottone Telegram, vince SEMPRE il
// valore non vuoto del gestionale; il foglio struttura conta solo se il
// gestionale è vuoto (transfer nuovo o mai assegnato).
if (!driverAssigned && autistaGestionale !== '') {
  autista = autistaGestionale;
}

// PATCH 2026-05-14 + 2026-07-23: stessa regola per Veicolo (gestionale vince se non vuoto)
let veicolo = s(src.Veicolo);
if (veicoloGestionale !== '') {
  veicolo = veicoloGestionale;
}

// =====================
// HIDE / ALLERT (LOGICA AGGIORNATA)
// =====================
const data = s(src.Data);
const today = todayIT();
const statoRaw = s(src.Stato).toLowerCase();
const isModifica = statoRaw.includes('modificato');

// Transfer era già assegnato? (autista presente nel gestionale O nel foglio struttura)
const eraAssegnato = autistaGestionale !== '' || autista !== '';

// 🆕 PATCH 2026-05-01: needsCancellatoSequence
// True se l'utente sta cambiando driver via Telegram (driverAssigned=true)
// E nel gestionale c'era già un driver DIVERSO. In quel caso il flusso a valle
// scrive prima Allert=Cancellato (al vecchio driver arriva il messaggio cancellato),
// aspetta 5s, poi scrive il nuovo driver + Allert=Invia.
const _cmpDrv = (x) => String(x||'').toLowerCase().replace(/\s+/g,' ').trim();
const needsCancellatoSequence = !!(driverAssigned
  && autistaGestionale
  && _cmpDrv(autistaGestionale) !== _cmpDrv(autista));
const oldDriverName = autistaGestionale || '';

let Hide, Allert;

if (driverAssigned) {
  // Autista assegnato da bottone Telegram → Invia + Hide = false (visibile)
  Allert = 'Invia';
  Hide = false;
} else if (isModifica && eraAssegnato) {
  // Modifica su transfer GIÀ ASSEGNATO → Allert "Modificato"
  Allert = 'Modificato';
  Hide = false;
} else {
  // Logica standard
  Hide = (autista !== '') ? false : (data === today ? false : true);
  Allert =
    (autista === '')
      ? (data === today ? 'Invia' : 'Non Inviare')
      : 'Invia';
}

// =====================
// WHATSAPP
// =====================
const cell = digits(src['cell.']);
const formulaWA = '=SE(  INDIRETTO("Y"&RIF.RIGA())="";  "";  "https://wa.me/" & INDIRETTO("X"&RIF.RIGA()) &  "?text=" &  ENCODEURL("Dear, this is Transfer Experience! We\'re reaching out about your transfer."))';
let WhatsApp;
if (cell) {
  const isItalian = cell.startsWith('39');
  const text = isItalian
    ? 'Gentile cliente, qui è Transfer Experience! La stiamo contattando in merito al suo transfer.'
    : "Dear, this is Transfer Experience! We're reaching out about your transfer.";
  WhatsApp = `https://wa.me/${cell}?text=${encodeURIComponent(text)}`;
} else {
  WhatsApp = formulaWA;
}

// =====================
// TARIFFA (AGGIORNATA: prezzo embedded + aggiustamenti ore/extra)
// =====================
const modalitaLower = modalitaVal.toLowerCase();
const tariffaInput = s(src['Tariffa a noi']);

// Formula completa di fallback (lookup prezzi dai listini — solo se nessun prezzo arriva)
const formulaTariffaLET =
'=SE('
+ 'INDIRETTO("J"&RIF.RIGA())="";'
+ '"";'
+ 'LET('
+ 'r;RIF.RIGA();'
+ 'mezzo;INDIRETTO("M"&r);'
+ 'is_special;O(mezzo="Tuk-tuk FT61049";mezzo="Ape Calessino DD63585");'
+ "alias;CERCA.X(INDIRETTO(\"J\"&r);'Fornitori e strutture'!A:A;SE(is_special;'Fornitori e strutture'!C:C;'Fornitori e strutture'!B:B));"
+ 'pax;VALORE(INDIRETTO("H"&r));'
+ "range_B;VALORE(INDIRETTO(\"'\"&alias&\"'!B1\"));range_C;VALORE(INDIRETTO(\"'\"&alias&\"'!C1\"));"
