// Legge gli autisti dal foglio "Autisti" e costruisce la tastiera inline
// FILTRO: Fisso, Extra, Tuk-tuk, Tuk-tuk colleghi, Emergenza con Stato diverso da OFF
// ORDINE: Fisso → Extra → Tuk-tuk → Tuk-tuk colleghi → Emergenza → alfabetico per nome
const autistiRows = $('Read Autisti').all();

const drivers = autistiRows
  .filter(r => {
    const nome = (r.json.Autisti || '').toString().trim();
    const cat = (r.json.Categoria || '').toString().trim().toLowerCase();
    const stato = (r.json.Stato || '').toString().trim().toLowerCase();

    // Scarta righe vuote o header tipo "Categoria: Fisso"
    if (!nome || nome.toLowerCase().startsWith('categoria:')) return false;

    // Solo categorie operative
    const categorieValide = ['fisso', 'extra', 'tuk-tuk', 'tuk-tuk colleghi', 'emergenza'];
    if (!categorieValide.includes(cat)) return false;

    // Esclude solo gli OFF (Chiamata, Stipendio e celle vuote passano)
    if (stato === 'off') return false;

    return true;
  })
  .map(r => ({
    nome: (r.json.Autisti || '').toString().trim(),
    cat:  (r.json.Categoria || '').toString().trim().toLowerCase()
  }));

// Ordine: fisso → extra → tuk-tuk → tuk-tuk colleghi → emergenza, poi alfabetico
const ordine = { 'fisso': 1, 'extra': 2, 'tuk-tuk': 3, 'tuk-tuk colleghi': 4, 'emergenza': 5 };
drivers.sort((a, b) =>
  (ordine[a.cat] || 99) - (ordine[b.cat] || 99) ||
  a.nome.localeCompare(b.nome, 'it')
);

// Dedup per nome
const uniqueDrivers = [...new Map(drivers.map(d => [d.nome, d])).values()].map(d => d.nome);

// Info transfer
const cercaData = $('Cerca id sheet').item.json;
const id = cercaData.Id || $('Code - Parse Callback').item.json.id; // 20/07 fallback: ricerca riga vuota -> id dal callback ASSEGNA| (fix 'Ref: undefined' / transfer Wells perso)
const chatId = $('Code - Parse Callback').item.json.telegramContext.chatId;
const messageId = $('Code - Parse Callback').item.json.telegramContext.messageId;
const originalText = $('Code - Parse Callback').item.json.originalText || '';

// Costruisci tastiera autisti (2 per riga)
// Callback = D|NomeAutista (senza ID, per evitare limite 64 byte Telegram)
// L'ID viene messo nel testo come Ref per il Parse Callback
const rows = [];
for (let i = 0; i < uniqueDrivers.length; i += 2) {
  const row = [];
  row.push({ text: uniqueDrivers[i], callback_data: `D|${uniqueDrivers[i]}` });
  if (i + 1 < uniqueDrivers.length) {
    row.push({ text: uniqueDrivers[i + 1], callback_data: `D|${uniqueDrivers[i + 1]}` });
  }
  rows.push(row);
}

// Bottone Conferma + Annulla in fondo
rows.push([
  { text: '✅ Conferma', callback_data: `YES|${id}` },
  { text: '❌ Annulla', callback_data: `NO|${id}` }
]);

// Testo con Ref ID per il callback driver
const newText = originalText + `\n\n🚐 *Seleziona autista:*\nRef: ${id}`;

return [{
  json: {
    chatId,
    messageId,
    text: newText,
    replyMarkupJson: JSON.stringify({ inline_keyboard: rows })
  }
}];

// =======================================================================
// Writeback su foglio Barche — gestisce CANCELLA e CONFERMA A/R
// =======================================================================
// Gira nel flusso CANCELLA (dopo click Cancella su Telegram).
// Legge i dati dal foglio Strutture tramite 'Cerca id sheet'.
//
// LOGICA:
//  - L'Id nel foglio Strutture ha suffisso -A / -R (es. TR-20260409-xxxx-A)
//  - Rimuoviamo il suffisso per ottenere l'Id BASE del foglio Barche
//  - azione 'cancella' -> svuota la cella Transfer (stringa vuota)
//  - Se l'azione NON è cancella, potrebbe essere una conferma ->
//    scrive "A: Confermato" o "R: Confermato" in base al suffisso
//  - Se Stato='Cancellato' e azione è vuota, forza azione='cancella'
//  - Transfer puro (senza suffisso -A/-R): nessun writeback barche

const src = $('Cerca id sheet').item.json;

// USA source_sheet_id (il Gestionale Boat Tour), NON sheet id (file struttura)
const sheetId    = src['source_sheet_id'] || src['sheet id'] || '';
const sheetName  = src['Name'] || '';
const idSuffixed = src['Id'] || '';
const stato      = String(src['Stato'] || '').trim();
let   azione     = String(src['azione'] || '').toLowerCase().trim();

// Se Stato è Cancellato ma azione è vuota, forza cancella
if (stato === 'Cancellato' && !azione) {
  azione = 'cancella';
}

// Rimuove suffisso -A o -R per avere l'Id base del foglio Barche
const baseId = String(idSuffixed).replace(/-(A|R)$/i, '');

// Estrai lettera leg dal suffisso Id (-A / -R)
const suffixMatch = String(idSuffixed).match(/-(A|R)$/i);
const legLetter = suffixMatch ? suffixMatch[1].toUpperCase() : '';

// Determina se è un transfer barche (ha suffisso -A/-R)
const isBarche = !!legLetter;

let nuovoValore = '';
let needWriteback = false;
let reason = '';

if (azione === 'cancella') {
  if (!isBarche) {
    // Transfer puro: nessun writeback sul file barche
    needWriteback = false;
    nuovoValore = '';
    reason = 'transfer puro, niente writeback barche';
  } else {
    // Transfer barche: svuota la cella Transfer nel file barche
    needWriteback = !!sheetId && !!baseId;
    nuovoValore = '';
    reason = needWriteback ? '' : 'sheetId o baseId mancanti';
  }
} else {
  // Non cancella (conferma/modifica): scrivi "X: Confermato"
  needWriteback = !!sheetId && !!baseId && !!legLetter;
  nuovoValore = needWriteback ? `${legLetter}: Confermato` : '';
  reason = needWriteback ? '' : 'sheetId/baseId/legLetter mancanti per conferma';
}

return [{
  json: {
    writeback: needWriteback ? 'ready' : 'skip',
    sheetId,
    sheetName,
    baseId: needWriteback ? baseId : '',
    legLetter,
    nuovoValore,
    azione,
    isBarche,
    reason
  }
}];

