// Match tra webhook e Queue per trovare lo SpreadsheetId del File Transfer
// Strategia:
//   1. Match esatto per Fornitore (colonna I della Queue, popolata da v3)
//   2. Fallback: match esatto per fileName
//   3. Fallback: contains match tra fornitore e FileName della Queue

function norm(str) {
  return (str || '').toString().trim().toLowerCase()
    .replace(/[àáâãä]/g, 'a')
    .replace(/[èéêë]/g, 'e')
    .replace(/[ìíîï]/g, 'i')
    .replace(/[òóôõö]/g, 'o')
    .replace(/[ùúûü]/g, 'u');
}

const srcFileName = $('Code - Build ID + Telegram1').item.json.fileName || '';
const fornitore = $('Code - Build ID + Telegram1').item.json.transfer.fornitore || '';
const srcFileNameNorm = norm(srcFileName);
const fornitoreNorm = norm(fornitore);

// Prendi tutte le righe del Queue
const allItems = $('Get Fornitore Sheet ID1').all();

let matched = null;

// 1. Match esatto per Fornitore (colonna I della Queue)
if (fornitoreNorm) {
  for (const item of allItems) {
    const qFornitore = norm(item.json.Fornitore);
    if (qFornitore && qFornitore === fornitoreNorm) {
      matched = item.json;
      break;
    }
  }
}

// 2. Fallback: match esatto per fileName
if (!matched && srcFileNameNorm) {
  for (const item of allItems) {
    const qfn = norm(item.json.FileName);
    if (qfn === srcFileNameNorm) {
      matched = item.json;
      break;
    }
  }
}

// 3. Fallback: il fornitore è contenuto nel FileName della Queue (o viceversa)
if (!matched && fornitoreNorm) {
  for (const item of allItems) {
    const qfn = norm(item.json.FileName);
    if (qfn && (qfn.includes(fornitoreNorm) || fornitoreNorm.includes(qfn))) {
      matched = item.json;
      break;
    }
  }
}

if (matched) {
  return [{ json: matched }];
} else {
  return [{ json: { FileName: '', SpreadsheetId: '', Fornitore: '', _noMatch: true, _searchedFor: fornitore || srcFileName } }];
}

// === Smart Write Struttura — Trova riga target e prepara dati ===
const src = $('Cerca id sheet').item.json;
const targetId = (src['Id'] || '').trim();
const allItems = $('Read Structure File').all();
const sheetId = src['sheet id'];
const sheetName = src['Name'];

if (!allItems.length || !sheetId || !sheetName) {
  return [{ json: { skip: true, reason: 'Nessuna riga o sheet id vuoto' } }];
}

const headers = Object.keys(allItems[0].json).filter(h => h !== 'row_number');

// 1. Cerca per Id
let targetRow = -1;
let targetIdx = -1;
let mode = '';
for (let i = 0; i < allItems.length; i++) {
  const idVal = (allItems[i].json['Id'] || '').toString().trim();
  if (idVal === targetId) {
    targetRow = i + 2;
    targetIdx = i;
    mode = 'update';
    break;
  }
}

// 2. Se nessun match, cerca prima riga vuota
if (targetRow === -1) {
  for (let i = 0; i < allItems.length; i++) {
    const r = allItems[i].json;
    const note = (r['Note'] || '').toString().trim();
    const data = (r['Data'] || '').toString().trim();
    const time = (r['Time'] || '').toString().trim();
    const da   = (r['TRS> DA'] || '').toString().trim();
    const per  = (r['TRS <PER'] || '').toString().trim();
    const pax  = (r['PAX'] || '').toString().trim();
    if (!note && !data && !time && !da && !per && !pax) {
      targetRow = i + 2;
      targetIdx = i;
      mode = 'empty_row';
      break;
    }
  }
}

if (targetRow === -1) {
  return [{ json: { skip: true, reason: 'Nessuna riga con Id e nessuna riga vuota' } }];
}

const existing = allItems[targetIdx]?.json || {};

// PATCH 2026-05-16: mail può vivere come 'mail' (nuovo nome) o 'n. pratica' (vecchio).
// src spesso porta la mail solo sotto 'n. pratica' (foglio sorgente legacy).
const incomingMail = ((src['mail'] || src['n. pratica'] || '') + '').trim();

// === COLONNE IGNORATE: non sovrascritte mai. Quel che c'è nel foglio
// (valore letterale o formula) resta intatto.
const IGNORED = new Set([
  'Veicolo',
  'h extra/ritardi',
  'Tariffa a noi',
  'Tariffa',
  'Fee',
  'Modalità',
  'Tipologia incasso',
  'Autista'   // 🆕 PATCH 2026-05-01: Smart Write Struttura non sovrascrive Autista sul foglio struttura cliente, evita race con propagazione Apps Script struttura→gestionale
]);

function isIgnored(h) {
  return IGNORED.has(h) || IGNORED.has((h || '').trim());
}

// 3. Prepara valori SOLO per le colonne NON ignorate
const writeData = {
  'Mese': src['Mese'] || '',
  'Note': src['Note'] || '',
  'Data': src['Data'] || '',
  'Time': src['Time'] || '',
  'TRS> DA': src['TRS> DA'] || '',
  'TRS <PER': src['TRS <PER'] || '',
  'PAX': src['PAX'] || '',
  'Nome': src['Nome'] || '',
  'Fornitore': src['Fornitore'] || '',
  'Volo': src['Volo'] || '',
  'cell.': src['cell.'] || '',
  'Autista': src['Autista'] || '',
  'n. pratica': incomingMail,
  'Addebitato': src['Addebitato'] || '',
  'Stato': 'Confermato',
  'Eseguito': src['Eseguito'] || '',
  'Id': targetId,
  'mail': incomingMail
};

// FIX 2026-04-19: rowValues tollera spazi negli header del foglio struttura
// e IGNORA completamente le colonne protette (riscrive esattamente quello
// che c'era nel foglio: valore letterale o formula).
// PATCH 2026-05-16: regola globale "no overwrite with empty".
// Se il valore in arrivo è stringa vuota / undefined e la cella esistente
// ha un valore, preserva la cella. Evita di cancellare campi (mail, Volo,
// cell., Autista, Note, ecc.) quando src non li propaga.
function pickValue(h) {
  if (isIgnored(h)) {
    return existing[h] !== undefined ? existing[h] : '';
  }
  let w;
  if (writeData[h] !== undefined) {
    w = writeData[h];
  } else {
    const trimmed = h.trim();
    if (writeData[trimmed] !== undefined) w = writeData[trimmed];
  }
  // PATCH 2026-05-16: se incoming vuoto/undefined ma esiste un valore, preserva.
  const incomingEmpty = (w === undefined) || (typeof w === 'string' && w.trim() === '');
  if (incomingEmpty) {
    return (existing[h] !== undefined && existing[h] !== '') ? existing[h] : (w !== undefined ? w : '');
  }
  return w;
}
const rowValues = headers.map(pickValue);

// FIX 2026-04-22: gestisce fogli con piu' di 26 colonne (AA, AB, ...)
function colIndexToLetter(n) {
  let s = '';
  while (n > 0) {
    const r = (n - 1) % 26;
    s = String.fromCharCode(65 + r) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}
const colLetter = colIndexToLetter(headers.length);
const range = `${sheetName}!A${targetRow}:${colLetter}${targetRow}`;

return [{ json: { sheetId, sheetName, targetRow, mode, range, rowValues, skip: false, ignored_columns: [...IGNORED] } }];

// =======================================================================
// Writeback Rifiuto Code
// =======================================================================
// Scrive sulla colonna "Transfer" del foglio Barche del fornitore SORGENTE:
//   "A: Rifiutato"  se Id finisce in -A
//   "R: Rifiutato"  se Id finisce in -R
//
// Si attiva sul ramo Declined (decision = NO) del TG Trigger.
// =======================================================================

const src = $('Cerca id sheet').item.json;

const sheetId    = src['source_sheet_id'] || src['sheet id'] || '';
const sheetName  = src['Name'] || '';
const idSuffixed = src['Id'] || '';

let decision = '';
try {
  decision = String($('Code - Parse Callback').item.json.decision || '').toUpperCase().trim();
} catch (e) {}

const suffixMatch = String(idSuffixed).match(/-(A|R)$/i);
const legLetter = suffixMatch ? suffixMatch[1].toUpperCase() : '';

const baseId = String(idSuffixed).replace(/-(A|R)$/i, '');

const shouldWriteback = (decision === 'NO')
                     && !!sheetId
                     && !!baseId
                     && !!legLetter;

const nuovoValore = shouldWriteback
  ? `${legLetter}: Rifiutato`
  : '';

// EARLY EXIT IF SKIP - evita crash su Writeback Rifiuto API per matching column vuoto
if (!shouldWriteback) {
  return [];
}
return [{
  json: {
    writeback: 'ready',
    sheetId,
    sheetName,
    baseId: shouldWriteback ? baseId : '',
    legLetter,
    nuovoValore,
    decision,
    reason: shouldWriteback ? '' : 'decision != NO o sheetId/baseId/legLetter mancanti'
  }
}];

// Calcola minutesToService e isOggi a partire da transfer.data e transfer.ora
const t = $('Code - Build ID + Telegram1').item.json.transfer || {};
const dataStr = String(t.data || '').trim();   // dd/MM/yyyy
const oraStr  = String(t.ora || '').trim();    // HH:mm
const idStr   = String(t.id || '').trim();
const autistaStr = String(t.autista || '').trim();

const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
let minutesToService = null;
let isOggi = false;

const md = dataStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
const mt = oraStr.match(/^(\d{1,2}):(\d{2})/);
if (md) {
  const dd = parseInt(md[1],10), mm = parseInt(md[2],10), yy = parseInt(md[3],10);
  isOggi = dd === today.getDate() && mm === today.getMonth()+1 && yy === today.getFullYear();
  if (mt) {
    const hh = parseInt(mt[1],10), min = parseInt(mt[2],10);
    const transferDate = new Date(yy, mm-1, dd, hh, min, 0);
    const nowItaly = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
    minutesToService = Math.round((transferDate - nowItaly) / 60000);
  }
}

return { json: {
  isOggi,
  minutesToService,
  shouldTriggerSubWorkflow: !!(isOggi && minutesToService !== null && minutesToService > 0 && minutesToService <= 120 && !autistaStr),
  transferData: t
}};

// Tocco su «✏️ Importo»: apro l'attesa e chiedo la cifra sul bot Prenotazioni,
// dove la macchina che legge i numeri scritti a mano esiste già (fatta il 12/08).
const cq = ($('TG Trigger - Callback').first().json || {}).callback_query || {};
