const ora = (testo.match(/⏰\s*([^\n]+)/) || [])[1] || '';
const attuale = (testo.match(/💶\s*([^\n–-]+)/) || [])[1] || '';
return [{ json: {
  id: id,
  callback_id: String(cq.id || ''),
  chatd: 'TARWAIT|' + '522233722',
  Dati: JSON.stringify({ ids: [id], t: Date.now(), token: 'struttura' }),
  riassunto: [quando.trim(), ora.trim(), tratta.trim()].filter(Boolean).join(' · '),
  attuale: attuale.trim()
} }];

// WF2 - Parse callback + authorization (CON ASSEGNA + DRIVER ASSIGN)

function toStr(v) { return (v ?? '').toString().trim(); }
function toInt(v) {
  const n = Number(toStr(v));
  return Number.isFinite(n) ? n : null;
}

function parseCallbackData(dataRaw) {
  const data = toStr(dataRaw);
  if (!data) throw new Error('WF2: callback_data vuota');

  const parts = data.split('|').map(p => (p ?? '').toString().trim());
  let decision = (parts[0] || '').toUpperCase().replace(/[^A-Z]/g, '');

  if (decision === 'SI' || decision === 'OK') decision = 'YES';
  if (decision === 'KO') decision = 'NO';

  // ===== DRIVER ASSIGN: D|nomeAutista (ID estratto dal testo messaggio) =====
  if (decision === 'D') {
    if (parts.length < 2) {
      throw new Error(`WF2: formato D richiede D|nomeAutista, ricevuto: "${data}"`);
    }
    // L'ID non è nel callback (limite 64 byte), lo estraiamo dal testo del messaggio
    // Il Build Driver Keyboard aggiunge "Ref: <ID>" alla fine del messaggio
    const msgText = (cq?.message?.text || '');
    const refMatch = msgText.match(/Ref:\s*(.+)/);
    const extractedId = refMatch ? refMatch[1].trim() : '';
    if (!extractedId) {
      throw new Error(`WF2: ID non trovato nel testo messaggio (Ref mancante)`);
    }
    return {
      decision: 'YES',
      driverName: parts[1],
      id: extractedId,
      isDriverAssign: true
    };
  }

  // ===== ASSEGNA: ASSEGNA|id =====
  if (decision === 'ASSEGNA') {
    return {
      decision: 'ASSEGNA',
      id: parts.length >= 2 ? parts.slice(1).join('|') : '',
      isDriverAssign: false,
      driverName: ''
    };
  }

  if (!['YES', 'NO', 'ESEGUITO'].includes(decision)) {
    throw new Error(`WF2: decision non valida: "${parts[0]}" (normalized: "${decision}") | raw: "${data}"`);
  }

  // LEGACY: YES|spreadsheetId|sheetName|rowIndex|id
  if (parts.length >= 5) {
    return { decision, spreadsheetId: parts[1], sheetName: parts[2], rowIndex: toInt(parts[3]), id: parts.slice(4).join('|'), isDriverAssign: false, driverName: '' };
  }
  // ATTUALE: YES|rowIndex|id
  if (parts.length === 3) {
    return { decision, rowIndex: toInt(parts[1]), id: parts[2], isDriverAssign: false, driverName: '' };
  }
  // MINIMO: YES|id
  if (parts.length === 2) {
    return { decision, id: parts[1], isDriverAssign: false, driverName: '' };
  }

  throw new Error(`WF2: callback_data non valida: "${data}"`);
}

const cq = $json.callback_query ?? $json;
const dataRaw   = cq?.data ?? null;
const actorId   = cq?.from?.id ?? null;
const actorUser = cq?.from?.username ?? cq?.from?.first_name ?? '';
const messageId = cq?.message?.message_id ?? null;
const chatId    = cq?.message?.chat?.id ?? null;
// Salva il testo originale del messaggio per poterlo riusare
const originalText = cq?.message?.text ?? '';

const parsed = parseCallbackData(dataRaw);

const ALLOWED = [522233722];
const unauthorized = (ALLOWED.length > 0) && (actorId != null) && (!ALLOWED.includes(Number(actorId)));

return [{
  json: {
    ...parsed,
    unauthorized,
    telegramContext: { chatId, messageId },
    originalText,
    actor: { actorId, actorUser },
    rawCallback: toStr(dataRaw)
  }
}];

// ===============================
// INPUT — dati transfer da "Cerca id sheet"
// ===============================
const data = $('Cerca id sheet').item.json;

// ===============================
// UTILS
// ===============================
const toStr = (v) => {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v.trim();
  return String(v).trim();
};

const toNum = (v) => {
  const s0 = toStr(v);
  if (!s0) return null;
  let s = s0.replace(/\s+/g, "");
  s = s.replace(/[€$£]/g, "");
  if (s.includes(",")) {
    s = s.replace(/\./g, "").replace(/,/g, ".");
  }
  s = s.replace(/[^0-9.+-]/g, "");
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const formatIT = (n) => {
  if (n === null || n === undefined || !Number.isFinite(n)) return "";
  return n.toFixed(2).replace(".", ",");
};

// ===============================
// LINGUA DAL NODO AI (Detect Language)
// ===============================
let lang = "en";
try {
  const aiOutput = $('Detect Language').item.json;
  const aiText = (
    aiOutput?.output?.[0]?.content?.[0]?.text ??
    aiOutput?.message?.content ??
    aiOutput?.content ??
    aiOutput?.text ??
    ""
  ).toString().toLowerCase().trim();
  lang = aiText.startsWith("it") ? "it" : "en";
} catch (e) {
  lang = "en";
}

// ===============================
// NOME STRUTTURA DINAMICO (dal Fornitore)
// ===============================
const nomeStruttura = toStr(data.Fornitore) || "Transfer Experience";

// ===============================
// ESTRAI DATI
// ===============================
const dataServizio = toStr(data.Data);
const ora = toStr(data.Time);
const trs_da = toStr(data['TRS> DA']);
const trs_per = toStr(data['TRS <PER']);
const nome = toStr(data.Nome);
const pax = toStr(data.PAX);
const volo = toStr(data.Volo);
const note = toStr(data.Note);
const cellulare = toStr(data['cell.']);
const modalita = toStr(data['Modalità']);
const tariffa = toNum(data['Tariffa '] || data.Tariffa);
const email = toStr(data['n. pratica']);
const hExtra = toStr(data['h extra/ritardi']);

// ===============================
// AUTO-DETECT VEICOLO IN BASE A PAX
// ===============================
const paxNum = parseInt(pax) || 0;
let veicolo = toStr(data.Veicolo);

if (!veicolo) {
  if (paxNum >= 1 && paxNum <= 2) {
    veicolo = "Auto";
  } else if (paxNum >= 3 && paxNum <= 7) {
    veicolo = "Minivan";
  } else if (paxNum >= 8) {
    veicolo = "Minibus";
  }
}

// ===============================
// TESTI MULTILINGUA (struttura dinamica)
// ===============================
const texts = {
  it: {
    subject: (nome, data, ora) => `🚗 Conferma Transfer - ${nome || 'Ospite'} - ${data} ore ${ora}`,
    title: "Conferma Prenotazione Transfer",
    subtitle: nomeStruttura,
