}

// ===============================
// COSTRUISCI EMAIL HTML
// ===============================
const emailSubject = t.subject(nome, dataServizio, ora);

const tariffaRow = tariffa !== null
  ? `<tr style="background-color: #f8f9fa;">
      <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">💰 ${t.price}</td>
      <td style="padding: 12px; border: 1px solid #dee2e6;">€ ${formatIT(tariffa)}</td>
    </tr>`
  : '';

const hExtraRow = hExtra
  ? `<tr>
      <td style="padding: 12px; border: 1px solid #dee2e6; font-weight: bold;">⏱️ ${t.hExtra}</td>
      <td style="padding: 12px; border: 1px solid #dee2e6;">${hExtra}</td>
    </tr>`
  : '';

const noteRow = note
