// ============================================================
// FUZZY MATCH – funzioni di normalizzazione e matching
// ============================================================

function norm(str) {
  return (str || '').toString().trim().toLowerCase()
    .replace(/[àáâãä]/g, 'a')
    .replace(/[èéêë]/g, 'e')
    .replace(/[ìíîï]/g, 'i')
    .replace(/[òóôõö]/g, 'o')
    .replace(/[ùúûü]/g, 'u')
    .replace(/[ñ]/g, 'n')
    .replace(/[''`]/g, "'")
    .replace(/[""«»]/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function alphaNum(str) {
  return norm(str).replace(/[^a-z0-9]/g, '');
}

function levenshtein(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      const cost = b[i - 1] === a[j - 1] ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[b.length][a.length];
}

function similarity(a, b) {
  const na = norm(a);
  const nb = norm(b);
  if (na === nb) return 1;
  if (!na || !nb) return 0;
  const maxLen = Math.max(na.length, nb.length);
  return 1 - (levenshtein(na, nb) / maxLen);
}

const STOP_WORDS = new Set([
  'di','a','da','in','con','su','per','tra','fra',
  'il','lo','la','i','gli','le','un','uno','una',
  'del','dello','della','dei','degli','delle',
  'al','allo','alla','ai','agli','alle',
  'dal','dallo','dalla','dai','dagli','dalle',
  'nel','nello','nella','nei','negli','nelle',
  'sul','sullo','sulla','sui','sugli','sulle',
  'e','o','ma','che','the','of','and'
]);

function tokenOverlap(a, b) {
  const tokA = new Set(norm(a).split(/\s+/).filter(t => t.length > 1 && !STOP_WORDS.has(t)));
  const tokB = new Set(norm(b).split(/\s+/).filter(t => t.length > 1 && !STOP_WORDS.has(t)));
  if (tokA.size === 0 || tokB.size === 0) return 0;
  let overlap = 0;
  for (const t of tokA) { if (tokB.has(t)) overlap++; }
  return overlap / Math.max(tokA.size, tokB.size);
}

function startsWithMatch(input, candidate) {
  const ni = norm(input);
  const nc = norm(candidate);
  return nc.startsWith(ni) || ni.startsWith(nc);
}

function containsMatch(input, candidate) {
  const ni = norm(input);
  const nc = norm(candidate);
  return nc.includes(ni) || ni.includes(nc);
}

function fuzzyMatch(input, candidates, soglia = 0.65) {
  const trimmed = (input || '').toString().trim();
  if (!trimmed) return { match: '', score: 0, method: 'empty' };

  const inputNorm = norm(trimmed);
  const inputAlpha = alphaNum(trimmed);

  let bestMatch = '';
  let bestScore = 0;
  let bestMethod = 'none';

  for (const candidate of candidates) {
    const candStr = (candidate || '').toString().trim();
    if (!candStr) continue;

    const candNorm = norm(candStr);
    const candAlpha = alphaNum(candStr);

    if (inputNorm === candNorm) {
      return { match: candStr, score: 1.0, method: 'exact' };
    }

    if (inputAlpha === candAlpha && inputAlpha.length > 2) {
      if (0.95 > bestScore) {
        bestMatch = candStr;
        bestScore = 0.95;
        bestMethod = 'alphanumeric';
      }
      continue;
    }

    if (startsWithMatch(trimmed, candStr) && candNorm.length > 2) {
      const lenRatio = Math.min(inputNorm.length, candNorm.length) / Math.max(inputNorm.length, candNorm.length);
      if (lenRatio >= 0.55) {
        const score = 0.85 * lenRatio + 0.15;
        if (score > bestScore) {
          bestMatch = candStr;
          bestScore = score;
          bestMethod = 'startsWith';
        }
      }
    }

    if (containsMatch(trimmed, candStr) && inputNorm.length >= 3) {
      const lenRatio = Math.min(inputNorm.length, candNorm.length) / Math.max(inputNorm.length, candNorm.length);
      if (lenRatio >= 0.55) {
        const score = 0.80 * lenRatio + 0.10;
        if (score > bestScore) {
          bestMatch = candStr;
          bestScore = score;
          bestMethod = 'contains';
        }
      }
    }

    const tOverlap = tokenOverlap(trimmed, candStr);
    if (tOverlap >= 0.65) {
      const score = 0.75 + (tOverlap * 0.15);
      if (score > bestScore) {
        bestMatch = candStr;
        bestScore = score;
        bestMethod = 'tokenOverlap';
      }
    }

    const sim = similarity(trimmed, candStr);
    if (sim >= soglia && sim > bestScore) {
      bestMatch = candStr;
      bestScore = sim;
      bestMethod = 'levenshtein';
    }
  }

  if (bestScore < soglia) {
    return { match: trimmed, score: bestScore, method: 'noMatch' };
  }

  return { match: bestMatch, score: bestScore, method: bestMethod };
}

