  const yyyy = parseInt(m[3], 10);
  const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
  return dd === today.getDate() && mm === (today.getMonth() + 1) && yyyy === today.getFullYear();
}
