\ud83d\udc64 ${escTg(newTransfer.nome || '-')} (${escTg(newTransfer.pax || '-')})
\ud83d\udcde ${escTg(newTransfer.cell || '-')}
\ud83c\udfe8 ${escTg(newTransfer.fornitore || '-')}
\ud83d\udcb6 ${escTg(newTransfer.tariffa || '-')}${newTransfer.modalita ? ` \u2014 ${escTg(newTransfer.modalita)}` : ''}${incassoLine}${newTransfer.note ? `\n\n\ud83d\udcdd ${escTg(newTransfer.note)}` : ''}`;

